"""Scree plot and cumulative proportion of variance for data generated by two latent factors."""

import numpy as np
import matplotlib.pyplot as plt

rng = np.random.default_rng(0)
n, p = 200, 8
f = rng.standard_normal((n, 2))
L = np.array([[0.9, 0.0], [0.8, 0.2], [0.85, 0.1], [0.7, 0.3],
              [0.1, 0.9], [0.2, 0.8], [0.0, 0.85], [0.3, 0.6]])
x = f @ L.T + 0.45 * rng.standard_normal((n, p))
R = np.corrcoef(x.T)
lam = np.sort(np.linalg.eigvalsh(R))[::-1]
k = np.arange(1, p + 1)

fig, axes = plt.subplots(1, 2, figsize=(11, 4.3))
ax = axes[0]
ax.plot(k, lam, "o-", color="C0")
ax.axhline(1, color="C3", ls="--", lw=1, label="eigenvalue 1 (Kaiser)")
ax.set_xlabel("component i")
ax.set_ylabel("eigenvalue of R")
ax.set_title("scree plot")
ax.legend()
ax.grid(alpha=0.3)

ax = axes[1]
ax.bar(k, np.cumsum(lam) / p, color="C0", alpha=0.7)
ax.axhline(0.8, color="C3", ls="--", lw=1, label="80%")
ax.set_ylim(0, 1.05)
ax.set_xlabel("number of components k")
ax.set_ylabel("cumulative proportion")
ax.set_title("cumulative proportion of variance")
ax.legend(loc="lower right")
ax.grid(alpha=0.3)
fig.tight_layout()
